 void appUpdateSettings(){android.content.SharedPreferences p=AppUpdates.prefs(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),0,dp(12),0);CheckBox auto=checkBox("Скачивать новые версии приложения автоматически",p.getBoolean("auto",false));box.addView(auto);CheckBox hourly=checkBox("Проверять раз в час",p.getBoolean("hourly",false));box.addView(hourly);box.addView(text("Без этой опции — раз в сутки после 07:00 МСК. Android может отложить проверку. Обновляется только GremlinAmp; музыка настраивается отдельно.",12,muted));CheckBox mobile=checkBox("Разрешить мобильную сеть",p.getBoolean("mobile",false));box.addView(mobile);box.addView(text("По умолчанию только Wi-Fi. APK проверяется по размеру, SHA-256, пакету, версии и подписи. Установку подтверждаете в системном окне Android. Скачанная музыка сохраняется.",12,muted));TextView result=text(p.getString("status","Проверка ещё не выполнялась"),13,fg);box.addView(result);Runnable save=()->{boolean changed=p.getBoolean("mobile",false)!=mobile.isChecked();p.edit().putBoolean("auto",auto.isChecked()).putBoolean("hourly",hourly.isChecked()).putBoolean("mobile",mobile.isChecked()).apply();if(changed){long id=p.getLong("download",-1);if(id!=-1&&AppUpdates.downloadState(this,id)!=android.app.DownloadManager.STATUS_SUCCESSFUL)AppUpdates.clear(this);}AppUpdates.schedule(this,true);};box.addView(button("Проверить и скачать сейчас",()->{save.run();result.setText("Проверяю сайт…");io.submit(()->{String message;try{message=AppUpdates.check(this);}catch(Exception e){message=AppUpdates.status(this,"Обновление: "+e.getMessage());}final String ready=message;runOnUiThread(()->result.setText(ready));});}));box.addView(button("Установить скачанное обновление",()->AppUpdates.install(this)));box.addView(button("Отменить скачивание / удалить APK",()->{AppUpdates.clear(this);result.setText(AppUpdates.status(this,"Скачанный APK удалён. Автопроверка: "+(p.getBoolean("auto",false)?"включена":"выключена")));}));ScrollView scroll=new ScrollView(this);scroll.addView(box);dialogBuilder().setTitle("Обновление GremlinAmp").setView(scroll).setPositiveButton("Сохранить",(d,w)->save.run()).setNegativeButton("Закрыть",null).show();}
