 void open(JSONObject g){int ticket=++requestId;message("Загружаю треклист…");io.submit(()->{try{JSONObject m=library.manifest(g,false);List<PlaybackService.Entry> queue=new ArrayList<>();for(int i=0;i<m.getJSONArray("tracks").length();i++)queue.add(new PlaybackService.Entry(g,m,i));runOnUiThread(()->{if(ticket!=requestId)return;album=g;manifest=m;albumQueue=queue;screen="tracks";reset();refreshDownloadStates();message(queue.size()+" композиций");});}catch(Exception e){if(ticket==requestId)message("Треклист: "+e.getMessage());}});}
 void setArt(String path){artPath=path;displayedArt=path;cover.setImageBitmap(path.isEmpty()?null:Library.artwork(new java.io.File(path)));}
