 void transport(Command action){playRequest++;command(action);}
 interface Command{void run(PlaybackService s);}void command(Command c){PlaybackService s=PlaybackService.instance;if(s!=null){c.run(s);return;}try{startForegroundService(new Intent(this,PlaybackService.class));awaitService(c,0);}catch(Exception e){message(e.getMessage());}}
 void awaitService(Command c,int tries){handler.postDelayed(()->{if(isFinishing())return;if(PlaybackService.instance!=null)c.run(PlaybackService.instance);else if(tries<20)awaitService(c,tries+1);else message("Не удалось запустить проигрыватель");},100);}
 static String trackKey(JSONObject track){JSONObject asset=track==null?null:track.optJSONObject("asset");return asset==null?"":asset.optString("sha256")+":"+track.optInt("subsong");}
 static String stamp(long ms){return String.format(Locale.ROOT,"%02d:%02d",ms/60000,ms/1000%60);}
 final Runnable tick=new Runnable(){public void run(){PlaybackService s=PlaybackService.instance;if(s!=null){if(cassette!=null)cassette.invalidate();PlaybackIdentity.View now=s.identity.snapshot();display.setText(now.title+(now.game.isEmpty()?"":"\n"+now.game));time.setText(stamp(s.currentPosition())+" / "+(s.durationKnown?stamp(s.duration):"--:--"));play.setText(s.paused||s.queue.isEmpty()?"Играть":"Пауза");play.setContentDescription(s.paused?"Продолжить воспроизведение":"Приостановить воспроизведение");play.setCompoundDrawablesRelativeWithIntrinsicBounds(new PlayerIcon(s.paused?"play":"pause",accent,dp(18)),null,null,null);play.setEnabled(!s.queue.isEmpty());seek.setEnabled(s.durationKnown&&s.duration>0&&!s.state.equals("loading")&&!s.state.equals("error"));if(!dragging&&!s.durationKnown)seek.setProgress(0);if(!dragging&&s.duration>0)seek.setProgress((int)(1000*s.currentPosition()/s.duration));if(screen.equals("tracks")&&album!=null&&!s.queue.isEmpty()){PlaybackService.Entry current=s.queue.get(s.position);for(int n=0;n<rows.getChildCount();n++){View row=rows.getChildAt(n);Object tag=row.getTag();if(tag!=null){boolean active=album.optString("id").equals(current.game.optString("id"))&&tag.equals(trackKey(current.manifest.optJSONArray("tracks").optJSONObject(current.index)));row.setBackground(surface(active?line:panel));row.setSelected(active);}}}
 if(!now.art.equals(displayedArt))setArt(now.art);playbackStatus.setText(s.state.equals("error")?"Ошибка: "+s.error:s.state.equals("loading")?"Загрузка композиции…":s.state.equals("continuing")?"Выбираю продолжение…":s.state.equals("ended")?(s.error.isEmpty()?"Очередь завершена":s.error):s.state.equals("idle")?"Выберите трек":s.paused?"Пауза":"Воспроизведение");}if(queueButton!=null){PlaybackService active=PlaybackService.instance;queueButton.setText(library.preferences.getBoolean("repeat",false)?"Повтор одного трека":library.preferences.getBoolean("loop",false)?"Повтор очереди":active!=null&&!active.nextGame.isEmpty()?"Далее: "+active.nextGame:"После коллекции: "+Continuation.label(library.preferences.getString("after_album","stop")));}if(DownloadService.instance!=null)status.setText(DownloadService.progress);long syncSuccess=library.preferences.getLong("sync_success",0);if(syncSuccess!=seenSyncSuccess){seenSyncSuccess=syncSuccess;reloadCachedCatalog();}if(seenRevision!=Library.revision.get()){seenRevision=Library.revision.get();refreshDownloadStates();}if(previousDownloadActive!=(DownloadService.instance!=null)){previousDownloadActive=DownloadService.instance!=null;updateDownloadButton();if(!previousDownloadActive)message(DownloadService.progress);}handler.postDelayed(this,400);}};
 void plan(List<JSONObject> list){plan(list,selectedSeries!=null&&!screen.equals("tracks")?selectedSeries.optString("id"):null);}
 void plan(List<JSONObject> list,String seriesId){plan(list,seriesId,false);}
 void plan(List<JSONObject> list,String seriesId,boolean wholeLibrary){List<JSONObject> copy=new ArrayList<>(list);if(copy.isEmpty()){message("Нет коллекций для загрузки");return;}if(selectionLabel(copy).equals("Скачано")&&!wholeLibrary&&seriesId==null){message("Эта музыка уже скачана");return;}message("Проверяю файлы…");io.submit(()->{try{long bytes=library.remaining(copy);runOnUiThread(()->{if(isFinishing())return;LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),0,dp(16),0);box.addView(text(String.format(Locale.ROOT,"Коллекций: %d\nНужно скачать: %.1f МБ\nСеть: %s",copy.size(),bytes/1048576.0,networkLabel()),14,fg));CheckBox followAll=null;if(wholeLibrary){followAll=checkBox("Добавлять новые игры сайта при автообновлении",true);box.addView(followAll);}final CheckBox allSubscription=followAll;CheckBox follow=null;if(seriesId!=null){follow=checkBox("Следить за всей серией: добавлять новые игры с музыкой",true);box.addView(follow);}final CheckBox subscribedSeries=follow;
 dialogBuilder().setTitle(bytes>0?"Скачать музыку":"Сохранить коллекцию").setView(box).setNegativeButton("Отмена",null).setPositiveButton(bytes>0?"Скачать":"Сохранить",(d,w)->{if(subscribedSeries!=null&&subscribedSeries.isChecked())library.trackSeries(seriesId);if(allSubscription!=null)library.preferences.edit().putBoolean("follow_all_music",allSubscription.isChecked()).apply();JSONArray rows=new JSONArray();for(JSONObject g:copy)rows.put(g);try{startForegroundService(new Intent(this,DownloadService.class).putExtra("games",rows.toString()));}catch(Exception e){message("Не удалось начать загрузку: "+e.getMessage());}}).show();});}catch(Exception e){message("Не удалось проверить файлы: "+e.getMessage());}});}
 void reloadCachedCatalog(){final int ticket=requestId;final String albumId=album==null?"":album.optString("id");io.submit(()->{try{JSONArray rows=library.catalog(false).getJSONArray("games");List<JSONObject> all=new ArrayList<>();for(int i=0;i<rows.length();i++)all.add(rows.getJSONObject(i));all=library.enrichGames(all);Set<String> ids=new HashSet<>();for(JSONObject g:all)ids.add(g.optString("id"));for(JSONObject saved:library.savedGames())if(ids.add(saved.optString("id")))all.add(saved);final List<JSONObject> ready=all;final JSONArray newSeries=library.series(false);JSONObject selected=null,newManifest=null;for(JSONObject g:all)if(g.optString("id").equals(albumId)){selected=g;newManifest=library.cachedManifest(g);break;}final JSONObject freshGame=selected,freshManifest=newManifest;runOnUiThread(()->{if(isFinishing())return;games=ready;series=newSeries;if(ticket==requestId){if(selectedSeries!=null)try{scope=filteredMembers(selectedSeries);}catch(Exception ignored){}else scope=new ArrayList<>(games);if(screen.equals("tracks")&&freshGame!=null&&freshManifest!=null){album=freshGame;manifest=freshManifest;albumQueue=new ArrayList<>();JSONArray ts=manifest.optJSONArray("tracks");for(int i=0;i<ts.length();i++)albumQueue.add(new PlaybackService.Entry(album,manifest,i));}refreshDownloadStates();alphabet();render();}message("Скачанная музыка обновлена");});}catch(Exception e){message("Музыка сохранена; каталог: "+e.getMessage());}});}
 void followedSeries(){if(series==null){message("Каталог серий ещё не загружен");return;}List<JSONObject> rows=new ArrayList<>();for(int i=0;i<series.length();i++){JSONObject row=series.optJSONObject(i);if(seriesCount(row)>0)rows.add(row);}rows.sort((a,b)->a.optString("title").compareToIgnoreCase(b.optString("title")));String[] labels=new String[rows.size()];boolean[] checked=new boolean[rows.size()];Set<String> saved=new HashSet<>(library.preferences.getStringSet("saved_series",Collections.emptySet()));for(int i=0;i<rows.size();i++){labels[i]=rows.get(i).optString("title");checked[i]=saved.contains(rows.get(i).optString("id"));}dialogBuilder().setTitle("Следить за сериями").setMultiChoiceItems(labels,checked,(d,i,on)->{String id=rows.get(i).optString("id");if(on)saved.add(id);else saved.remove(id);}).setPositiveButton("Сохранить",(d,w)->library.preferences.edit().putStringSet("saved_series",saved).apply()).setNegativeButton("Отмена",null).show();}
 void downloadAll(){message("Читаю полный каталог сайта…");io.submit(()->{try{JSONArray rows=library.freshJson(Library.BASE+"assets/gallery-music.json").getJSONArray("games");List<JSONObject> all=new ArrayList<>();for(int i=0;i<rows.length();i++)all.add(rows.getJSONObject(i));runOnUiThread(()->{if(!isFinishing())plan(all,null,true);});}catch(Exception e){message("Полный каталог недоступен: "+e.getMessage());}});}
 String networkLabel(){return library.preferences.getString("network","wifi").equals("wifi")?"только Wi-Fi":"Wi-Fi и мобильная";}
