 void filters(){dialogBuilder().setTitle("Фильтры библиотеки").setItems(new String[]{platformLabel(),yearLabel(),filterLabel(),"Сбросить фильтры"},(d,i)->{if(i==0)chooseFacet(false);if(i==1)chooseFacet(true);if(i==2)shortFilter();if(i==3)clearFilters();}).show();}
 void queueSettings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),0,dp(12),0);String[] keys={"shuffle","repeat","loop"},names={"Перемешивать треки","Повторять один трек","Повторять очередь"};for(int i=0;i<keys.length;i++){final int k=i;CheckBox c=checkBox(names[i],library.preferences.getBoolean(keys[i],false));c.setOnCheckedChangeListener((v,on)->{library.preferences.edit().putBoolean(keys[k],on).apply();PlaybackService p=PlaybackService.instance;if(p!=null){if(k==0)p.shuffle=on;if(k==1)p.repeat=on;if(k==2)p.repeatCollection=on;}});box.addView(c);}
 box.addView(text("После коллекции",14,fg));String[] modes={"stop","series","genre","similar","rhythm","sound"};RadioGroup options=new RadioGroup(this);for(int i=0;i<modes.length;i++){RadioButton b=new RadioButton(this);b.setId(100+i);b.setText(Continuation.label(modes[i]));b.setTextColor(fg);b.setMinHeight(dp(48));options.addView(b);if(modes[i].equals(library.preferences.getString("after_album","stop")))options.check(b.getId());}options.setOnCheckedChangeListener((g,id)->{library.preferences.edit().putString("after_album",modes[id-100]).apply();PlaybackService p=PlaybackService.instance;if(p!=null)p.refreshContinuation();});box.addView(options);
 CheckBox local=checkBox("Продолжать только скачанное",library.preferences.getBoolean("continue_local",true));local.setOnCheckedChangeListener((v,on)->{library.preferences.edit().putBoolean("continue_local",on).apply();PlaybackService p=PlaybackService.instance;if(p!=null)p.refreshContinuation();});box.addView(local);box.addView(text("Режим применяется после очереди. «Похожие игры» учитывает данные игр; «По ритму» и «По звучанию» выбирают отдельные треки по серверному анализу. Повтор трека и очереди имеет приоритет. Повторы уже звучавшей музыки исключаются в акустических режимах.",12,muted));box.addView(text(SimilarityStore.status(library),12,muted));box.addView(button("Обновить индекс похожей музыки",()->{message("Обновляю индекс похожей музыки…");io.submit(()->{SimilarityStore.refresh(library);message(SimilarityStore.status(library));PlaybackService player=PlaybackService.instance;if(player!=null)runOnUiThread(player::refreshContinuation);});}));ScrollView scroll=new ScrollView(this);scroll.addView(box);dialogBuilder().setTitle("Очередь и продолжение").setView(scroll).setPositiveButton("Готово",null).show();}
 void syncSettings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),0,dp(12),0);CheckBox auto=checkBox("Обновлять скачанную музыку автоматически",library.preferences.getBoolean("auto_music",false));box.addView(auto);box.addView(text("Когда проверять обновления",14,fg));RadioGroup intervals=new RadioGroup(this);String[] intervalNames={"Раз в час","Раз в сутки · после 07:00 МСК"};for(int i=0;i<2;i++){RadioButton b=new RadioButton(this);b.setId(400+i);b.setText(intervalNames[i]);b.setTextColor(fg);b.setMinHeight(dp(48));intervals.addView(b);}intervals.check(library.preferences.getString("sync_interval","daily").equals("hourly")?400:401);box.addView(intervals);box.addView(text("Сайт обычно заканчивает обновление к 06:00 МСК. Android может отложить фоновую проверку. Новые игры добавляются для выбранных серий или всей библиотеки, если вы скачивали её целиком.",12,muted));RadioGroup networks=new RadioGroup(this);for(int i=0;i<2;i++){RadioButton b=new RadioButton(this);b.setId(300+i);b.setText(i==0?"Только Wi-Fi":"Wi-Fi и мобильная сеть");b.setTextColor(fg);b.setMinHeight(dp(48));networks.addView(b);}networks.check(library.preferences.getString("network","wifi").equals("wifi")?300:301);box.addView(networks);CheckBox followAll=checkBox("Добавлять музыку новых игр сайта",library.preferences.getBoolean("follow_all_music",false));box.addView(followAll);box.addView(button("Серии для автообновления",this::followedSeries));box.addView(text("Выбор сети действует и на загрузку музыки при прослушивании. Скачанное играет без сети.",12,muted));long when=library.preferences.getLong("sync_success",0);box.addView(text("Последнее обновление: "+(when==0?"ещё не выполнялось":android.text.format.DateFormat.format("dd.MM HH:mm",when))+"\n"+library.preferences.getString("sync_status",""),12,muted));ScrollView scroll=new ScrollView(this);scroll.addView(box);
 Runnable save=()->{library.preferences.edit().putBoolean("auto_music",auto.isChecked()).putBoolean("follow_all_music",followAll.isChecked()).putString("sync_interval",intervals.getCheckedRadioButtonId()==400?"hourly":"daily").putString("network",networks.getCheckedRadioButtonId()==300?"wifi":"any").apply();MusicSyncJob.schedule(this,true);};dialogBuilder().setTitle("Обновления музыки и сеть").setView(scroll).setPositiveButton("Сохранить",(d,w)->{save.run();load();}).setNeutralButton("Проверить сейчас",(d,w)->{save.run();try{startForegroundService(new Intent(this,DownloadService.class).putExtra("sync",true));}catch(Exception e){message(e.getMessage());}}).setNegativeButton("Отмена",null).show();}
 String selectionLabel(List<JSONObject> selected){if(selected.isEmpty())return "Скачать";boolean all=true,any=false,saveOnly=true;for(JSONObject g:selected)if(!downloadStates.containsKey(g.optString("id")))return "Проверка…";for(JSONObject g:selected){String state=downloadStates.getOrDefault(g.optString("id"),"");all&=state.equals("Скачано");saveOnly&=state.equals("Сохранить")||state.equals("Скачано");any|=state.equals("Скачано")||state.startsWith("Докачать");}boolean updates=false;for(JSONObject g:selected)updates|=downloadStates.getOrDefault(g.optString("id"),"").startsWith("Есть обновления");return all?"Скачано":saveOnly?"Сохранить":updates?"Обновить":any?"Докачать":"Скачать";}
 String seriesSavedLabel(JSONObject r){try{List<JSONObject> list=filteredMembers(r);int saved=0;for(JSONObject g:list)if("Скачано".equals(downloadStates.get(g.optString("id"))))saved++;return "Скачано игр: "+saved+"/"+list.size();}catch(Exception e){return "";}}
 void updateDownloadButton(){if(downloadButton==null)return;boolean busy=DownloadService.instance!=null;String label=busy?"Загрузка…":selectionLabel(downloadSelection());downloadButton.setText(label);downloadButton.setEnabled(!busy&&!label.equals("Скачано")&&!label.equals("Проверка…")&&!downloadSelection().isEmpty());downloadButton.setAlpha(downloadButton.isEnabled()?1f:.55f);}
 void refreshDownloadStates(){final int token=++statusRequest;List<JSONObject> list=new ArrayList<>(games);if(album!=null&&!list.contains(album))list.add(album);io.submit(()->{Map<String,String> states=new HashMap<>();for(JSONObject g:list)states.put(g.optString("id"),library.downloadLabel(g));runOnUiThread(()->{if(!isFinishing()&&token==statusRequest){downloadStates=states;render();}});});}
